def _appv38_svg_graph_html(graph, height=650, label_limit=42, initial_scale=1.0):
    g = _appv38_normalize_graph(graph)
    nodes = _appv38_safe_list(g.get('nodes'))
    edges = _appv38_safe_list(g.get('edges'))
